// A budget's stop is reported as that budget, not as the precision cap. fuzz-8's d1 session case
// 5687255704371452872 (the conjugate, cluster and repeated-factor generator, degree 48, integer coefficients below
// 2^1100): its real roots in [22/7, inf) at the approximation goal, 16 bits, with 16 live cells, 100 work units and a
// 4,096-bit cap. Two exact square-free factors' covers overlap; one is blocked by the cell budget. Until 21 October
// 2026 every pass that found one factor finished and the other blocked counted as finished, so the overlap branch
// raised the blocked factor's separation goal again, 59 times at no work, up to its ceiling, and the solve stopped
// "at the precision cap of 4096 bits" while working at 128. Checked: the
// solve stops for the cell budget, the precision stop never comes below the cap, and the work is the solve's own.
#include "exact_winding_api.hpp"
#include <certpolysolve/certpolysolve.hpp>
#include <iostream>

using namespace reference;

namespace {
// The case file's ascending coefficients (the harness's `--describe`, its input to cps_polynomial_set_coefficient).
const char *const coefficients[] = {
    "-",
    "",
    "-",
    "",
    "-",
    "",
    "-",
    "",
    "-",
    "",
    "-",
    "",
    "-",
    "",
    "-",
    "",
    "-",
    "",
    "-",
    "",
    "-",
    "",
    "-",
    "",
    "-",
    "",
    "-",
    "",
    "-",
    "",
    "-",
    "",
    "-",
    "",
    "-",
    "",
    "-",
    "",
    "-",
    "",
    "-",
    "",
    "-",
    "",
    "-",
    "",
    "-",
    "",
    "-",
};
} // namespace

int main() {
    certpolysolve::ThreadScope lifetime;
    try {
        certpolysolve::Polynomial input;
        for (size_t j = 0; j < std::size(coefficients); ++j)
            input.set(j, certpolysolve::Number(coefficients[j]));
        require(input.ok(), "the input recorded a bad value");
        certpolysolve::Options options;
        options.goal = certpolysolve::Goal::approximation();
        options.bits = 16;
        options.max_bits = 4096;
        options.work_budget = 100;
        options.cell_budget = 16;
        const auto result = certpolysolve::real_roots(input, certpolysolve::at_least(certpolysolve::Number("22/7")), options);
        const auto stop = cps_result_stop_reason(result.get());
        const auto spent = result.statistics();
        // A precision stop is a stop at the cap: one below it names the wrong budget.
        require(stop != CPS_STOP_PRECISION || spent.highest_work_bits >= options.max_bits,
                "a precision stop below the precision cap");
        require(result.goal_met() || stop == CPS_STOP_CELL_BUDGET,
                "the solve did not stop for the cell budget that blocks it");
        // The overlap branch no longer raises the goal at no work: the stop comes well inside the work budget.
        require(spent.work_units < *options.work_budget, "the solve spent the whole work budget");
        std::cout << "stall label tests passed\n";
        return 0;
    } catch (const std::exception &error) {
        std::cerr << "FAILED: " << error.what() << '\n';
        return 1;
    }
}
